from collections import deque
from threading import Thread, Lock

class Solution:
    def crawl(self, startUrl: str, htmlParser: 'HtmlParser') -> List[str]:
        def hostname(url):
            return url[7:].split('/')[0]
        host = hostname(startUrl)
        q = deque([startUrl])
        seen = {startUrl}
        lock = Lock()
        ans = []
        active = [0]
        done = [False]

        def worker():
            while True:
                if not q:
                    if active[0] == 0:
                        done[0] = True
                    if done[0]:
                        return
                    continue
                url = q.popleft()
                active[0] += 1
                for nxt in htmlParser.getUrls(url):
                    if nxt not in seen and hostname(nxt) == host:
                        seen.add(nxt)
                        q.append(nxt)
                active[0] -= 1

        threads = [Thread(target=worker) for _ in range(8)]
        for t in threads: t.start()
        for t in threads: t.join()
        return list(seen)

