class Solution {
public:
    vector<string> crawl(string startUrl, HtmlParser htmlParser) {
        auto host = [](const string& u) {
            string s = u.substr(7);
            return s.substr(0, s.find('/'));
        };
        string target = host(startUrl);
        mutex m;
        condition_variable cv;
        unordered_set<string> seen{startUrl};
        queue<string> q;
        q.push(startUrl);
        int active = 0;
        bool finished = false;

        auto worker = [&]() {
            while (true) {
                unique_lock<mutex> lk(m);
                cv.wait(lk, [&] { return !q.empty() || finished; });
                if (finished && q.empty()) return;
                string url = q.front(); q.pop();
                lk.unlock();
                vector<string> urls = htmlParser.getUrls(url);
                lk.lock();
                for (auto& nxt : urls) {
                    if (!seen.count(nxt) && host(nxt) == target) {
                        seen.insert(nxt);
                        q.push(nxt);
                    }
                }
                if (--active == 0 && q.empty()) {
                    finished = true;
                    cv.notify_all();
                }
            }
        };

        {
            lock_guard<mutex> lk(m);
            active = 1;
        }
        vector<thread> ts;
        for (int i = 0; i < 8; i++) ts.emplace_back(worker);
        for (auto& t : ts) t.join();
        return vector<string>(seen.begin(), seen.end());
    }
};

