import java.util.*;
import java.util.concurrent.*;

class Solution {
    public List<String> crawl(String startUrl, HtmlParser htmlParser) {
        String host = hostname(startUrl);
        Set<String> seen = ConcurrentHashMap.newKeySet();
        seen.add(startUrl);
        Queue<String> queue = new ConcurrentLinkedQueue<>();
        queue.add(startUrl);
        AtomicInteger active = new AtomicInteger(1);
        int nThreads = 8;
        CountDownLatch latch = new CountDownLatch(nThreads);
        Runnable worker = () -> {
            while (true) {
                String url = queue.poll();
                if (url == null) {
                    if (active.get() == 0) break;
                    try { Thread.sleep(5); } catch (InterruptedException e) { return; }
                    continue;
                }
                for (String next : htmlParser.getUrls(url)) {
                    if (next.contains(host) && hostname(next).equals(host) && seen.add(next)) {
                        queue.add(next);
                        active.incrementAndGet();
                    }
                }
                active.decrementAndGet();
            }
            latch.countDown();
        };
        for (int i = 0; i < nThreads; i++) new Thread(worker).start();
        try { latch.await(); } catch (InterruptedException e) {}
        return new ArrayList<>(seen);
    }

    private String hostname(String url) {
        String s = url.substring(7);
        int idx = s.indexOf('/');
        return idx < 0 ? s : s.substring(0, idx);
    }
}

