from concurrent.futures import ThreadPoolExecutor
from threading import Lock

class Solution:
    def crawl(self, startUrl: str, htmlParser: 'HtmlParser') -> List[str]:
        host = startUrl[7:].split('/')[0]
        seen = {startUrl}
        lock = Lock()
        pending = [1]
        pool = ThreadPoolExecutor(max_workers=10)

        def visit(url):
            for nxt in htmlParser.getUrls(url):
                if nxt[7:].split('/')[0] != host:
                    continue
                with lock:
                    if nxt in seen:
                        continue
                    seen.add(nxt)
                    pending[0] += 1
                pool.submit(visit, nxt)
            with lock:
                pending[0] -= 1
                if pending[0] == 0:
                    pool.shutdown(wait=False)

        pool.submit(visit, startUrl)
        pool.shutdown(wait=True)
        return list(seen)

