import java.util.*;
import java.util.concurrent.*;

class Solution {
    public List<String> crawl(String startUrl, HtmlParser htmlParser) {
        String host = hostname(startUrl);
        Set<String> seen = ConcurrentHashMap.newKeySet();
        seen.add(startUrl);
        ExecutorService pool = Executors.newFixedThreadPool(10);
        AtomicInteger pending = new AtomicInteger(1);

        Runnable[] visitHolder = new Runnable[1];
        visitHolder[0] = () -> {};
        class Visitor implements Runnable {
            final String url;
            Visitor(String u) { url = u; }
            public void run() {
                for (String next : htmlParser.getUrls(url)) {
                    if (!hostname(next).equals(host)) continue;
                    if (seen.add(next)) {
                        pending.incrementAndGet();
                        pool.submit(new Visitor(next));
                    }
                }
                if (pending.decrementAndGet() == 0) pool.shutdown();
            }
        }
        pool.submit(new Visitor(startUrl));
        try {
            pool.awaitTermination(60, TimeUnit.SECONDS);
        } catch (InterruptedException e) {}
        return new ArrayList<>(seen);
    }

    private String hostname(String url) {
        String s = url.substring(7);
        int idx = s.indexOf('/');
        return idx < 0 ? s : s.substring(0, idx);
    }
}

